// kM0 = 1 is saturation, |M|/M(0). kMAnchor is the 300 K expansion point.
// Carrier powers use dr = (1 - m/kM0) - kRhoAnchor, which is zero there.
// The channel split is linear in m/kMAnchor. Magnon powers use
// [1-(m/kM0)^2] - [1-(kMAnchor/kM0)^2].
static inline double surface_factor(const double Te, const double m, const Surface& law){
   const double xi = (Te - kAnchorT) / kTeSpan;
   const double dr = (1.0 - m / kM0) - kRhoAnchor;
   double value = 1.0;
   double xp = xi;
   for(unsigned i = 0; i < law.nt; ++i){
      value += law.ct[i] * xp;
      xp *= xi;
   }
   double rp = dr;
   for(unsigned j = 0; j < law.nm; ++j){
      value += law.cm[j] * rp;
      rp *= dr;
   }
   xp = xi;
   for(unsigned i = 0; i < law.nct; ++i){
      rp = dr;
      for(unsigned j = 0; j < law.ncm; ++j){
         value += law.cross[i][j] * xp * rp;
         rp *= dr;
      }
      xp *= xi;
   }
   return value;
}

static inline void channel_diffusion(const double Tp, const double m, double& d_up, double& d_down){
   const double reduced_m = m / kM0;
   const double split = reduced_m * (kM0 / kMAnchor);
   const double reduced_tp = Tp / kAnchorT;
   const double dTp = reduced_tp - 1.0;
   const double phonon = kAPh * dTp + kBPh * dTp * dTp;
   const double missing = 1.0 - reduced_m * reduced_m;
   const double anchor_reduced = kMAnchor / kM0;
   const double dx = missing - (1.0 - anchor_reduced * anchor_reduced);
   const double magnon = kGMag[0] * dx + kGMag[1] * dx * dx + kGMag[2] * dx * dx * dx;
   const double up_rate = kRateMid + split * (kRateUp0 - kRateMid) + phonon + magnon;
   const double down_rate = kRateMid + split * (kRateDown0 - kRateMid) + phonon + magnon;
   d_up = 1.0 / std::max(up_rate, 1.0e-30);
   d_down = 1.0 / std::max(down_rate, 1.0e-30);
}

static inline Result evaluate(const double Te, const double Tp, const double ml){
   const double m = std::max(ml, 0.0);
   double d_up = 0.0;
   double d_down = 0.0;
   channel_diffusion(Tp, m, d_up, d_down);
   const double n_up = std::max(surface_factor(Te, m, kNUp), 1.0e-30);
   const double n_down = std::max(surface_factor(Te, m, kNDown), 1.0e-30);
   const double sigma_up = kSigmaUp0 * n_up * (d_up / kDUp0);
   const double sigma_down = kSigmaDown0 * n_down * (d_down / kDDown0);
   const double sigma = std::max(sigma_up + sigma_down, 1.0e-300);
   const double beta_c = (sigma_up - sigma_down) / sigma;
   const double d_sum = std::max(d_up + d_down, 1.0e-300);
   const double beta_d = (d_up - d_down) / d_sum;
   const double weight_up = n_up * kSigmaUp0 / kDUp0;
   const double weight_down = n_down * kSigmaDown0 / kDDown0;
   const double weight_sum = std::max(weight_up + weight_down, 1.0e-300);
   const double d_bar = (weight_up * d_up + weight_down * d_down) / weight_sum;
   const double p_n = (n_up * kNUp0 - n_down * kNDown0)
      / std::max(n_up * kNUp0 + n_down * kNDown0, 1.0e-300);
   const double p_n0 = (kNUp0 - kNDown0) / (kNUp0 + kNDown0);
   const double alpha = ((n_up * kNUp0) + (n_down * kNDown0))
      / std::max(2.0 * (n_up * kNUp0) * (n_down * kNDown0), 1.0e-300);
   const double alpha0 = (kNUp0 + kNDown0) / (2.0 * kNUp0 * kNDown0);
   Result r;
   r.beta_c = beta_c;
   r.beta_d = beta_d;
   r.diffusion_ratio = d_bar / kDBar0;
   r.lambda_sdl_ratio = std::sqrt(std::max(r.diffusion_ratio, 0.0));
   r.sigma_ratio = sigma / kSigma0;
   r.pn_ratio = (std::fabs(p_n0) > 1.0e-30) ? (p_n / p_n0) : 1.0;
   r.alpha_ratio = alpha / alpha0;
   return r;
}

